/**
 * Normalizes language codes or subject names to supported key.
 */
export function normalizeLanguageCode(langOrSubjectId) {
  if (!langOrSubjectId) return null;
  const str = String(langOrSubjectId).trim().toLowerCase();
  for (const [code, info] of Object.entries(REGIONAL_LANG_INFO)) {
    if (code === str || info.id === str) return code;
  }
  return null;
}

/**
 * Returns regional language subject for a given grade and language.
 */
export function getRegionalLanguageSubject(grade, langOrSubjectId) {
  const code = normalizeLanguageCode(langOrSubjectId);
  if (!code) return null;
  const info = REGIONAL_LANG_INFO[code];
  const gradeChapters = REGIONAL_CURRICULUM[code]?.[Number(grade)];
  if (!info || !gradeChapters) return null;

  return {
    id: info.id,
    name: `${info.name} (${info.nativeName})`,
    icon: info.icon,
    code: info.code,
    chapters: gradeChapters.map(([chapterId, title, reading, fact, falseFact, prompt, answer]) => ({
      id: chapterId,
      title,
      reading,
      fact,
      falseFact,
      prompt,
      answer,
    })),
  };
}

export function getAllRegionalLanguageCodes() {
  return Object.keys(REGIONAL_LANG_INFO);
}
